    },
    "issue_date": {
      "type": "string",
      "description": "Issue / effective / report period end date as YYYY-MM-DD, or empty string"
    },
    "expiry_date": {
      "type": "string",
      "description": "Expiry / policy end / contract end / certificate valid-until date as YYYY-MM-DD, or empty string"
    },
    "coverage_amount": {
      "type": "string",
      "description": "For insurance: per-occurrence / aggregate limits, otherwise empty"
    },
    "summary": {
      "type": "string",
      "description": "One sentence describing the document"
    },
    "confidence": {
      "type": "number",
      "description": "0-1 confidence in the extraction"
    }
  },
  "required": [
    "vendor_name",
    "doc_type",
    "issuer",
    "issue_date",
    "expiry_date",
    "coverage_amount",
    "summary",
    "confidence"
  ]
}

