// Combine Drive file metadata with the AI extraction (1:1 by item index)
const file = $('Check If PDF').all()[$itemIndex].json;
const x = $json.output || {};
return {
  json: {
    file_id: file.id,
    file_name: file.name,
    file_url: file.webViewLink || `https://drive.google.com/file/d/${file.id}/view`,
    ai_vendor_name: (x.vendor_name || '').trim(),
    doc_type: x.doc_type || 'Other',
    issuer: x.issuer || '',
    issue_date: x.issue_date || '',
    expiry_date: x.expiry_date || '',
    coverage_amount: x.coverage_amount || '',
    summary: x.summary || '',
    ai_confidence: Number(x.confidence ?? 0),
  }
};

// Match each extracted document to a vendor and decide whether it needs human review
const records = $('Build Document Records').all().map(i => i.json);
const vendors = $input.all().map(i => i.json).filter(v => v.vendor_id);
const norm = s => String(s || '').toLowerCase()
  .replace(/\b(inc|llc|ltd|limited|corp|corporation|co|pvt|private|plc|gmbh|the)\b\.?/g, '')
  .replace(/[^a-z0-9]/g, '');
const EXPIRING = ['Insurance Certificate','Contract','Security Certification','SOC 2 Report','ISO Certificate','Business License'];

return records.map(r => {
  let vendor = null, how = '';
  // 1) vendor_id at the start of the file name, e.g. "V-0042_COI_2026.pdf"
  vendor = vendors.find(v => r.file_name.toLowerCase().startsWith(String(v.vendor_id).toLowerCase()));
  if (vendor) how = 'file name';
  // 2) exact normalised name, 3) contains
  if (!vendor && r.ai_vendor_name) {
    const n = norm(r.ai_vendor_name);
    vendor = vendors.find(v => norm(v.vendor_name) === n);
    if (vendor) how = 'exact name';
    if (!vendor && n.length > 3) {
      vendor = vendors.find(v => { const vn = norm(v.vendor_name); return vn.length > 3 && (vn.includes(n) || n.includes(vn)); });
      if (vendor) how = 'partial name';
    }
  }
  const reasons = [];
  if (!vendor) reasons.push(`No vendor match for "${r.ai_vendor_name || 'unknown'}"`);
  if (how === 'partial name') reasons.push('Vendor matched on partial name');
  if (r.ai_confidence < 0.7) reasons.push(`Low AI confidence (${r.ai_confidence})`);
  if (r.doc_type === 'Other') reasons.push('Unrecognised document type');
  if (EXPIRING.includes(r.doc_type) && !r.expiry_date) reasons.push('No expiry date found');
  if (r.doc_type === 'Bank Information') reasons.push('Bank details changed - call-back verification required before payment');

  return { json: {
    doc_id: r.file_id,
    vendor_id: vendor ? vendor.vendor_id : '',
    vendor_name: vendor ? vendor.vendor_name : r.ai_vendor_name,
    doc_type: r.doc_type,
    file_name: r.file_name,
    file_id: r.file_id,
    file_url: r.file_url,
    issuer: r.issuer,
    issue_date: r.issue_date,
    expiry_date: r.expiry_date,
    coverage_amount: r.coverage_amount,
    summary: r.summary,
    verified: 'FALSE',
    ai_confidence: r.ai_confidence,
    needs_review: reasons.length ? 'TRUE' : 'FALSE',
    review_reason: reasons.join('; '),
    last_updated: new Date().toISOString(),
  }};
});

