// Tier requirements - which documents each vendor tier must hold.
// anyOf = any one of these document types satisfies the requirement.
return [{ json: {
  ...$('Set Compliance Parameters').first().json,
  // validity used when a doc has an issue date but no expiry date
  defaultValidityDays: { 'SOC 2 Report': 365, 'Security Certification': 365 },
  // document types that must carry an expiry date
  expiringTypes: ['Insurance Certificate','Contract','Security Certification','SOC 2 Report','ISO Certificate','Business License'],
  // requirements per vendor tier; anyOf = any one of these document types satisfies it
  requirements: {
    Critical: [
      { name: 'Insurance (COI)',        anyOf: ['Insurance Certificate'], critical: true },
      { name: 'NDA',                    anyOf: ['NDA'], critical: true },
      { name: 'Contract / MSA',         anyOf: ['Contract'], critical: true },
      { name: 'Tax document (W-9/W-8)', anyOf: ['Tax Document'] },
      { name: 'Security attestation',   anyOf: ['SOC 2 Report','ISO Certificate','Security Certification'], critical: true },
      { name: 'Business license',       anyOf: ['Business License'] },
      { name: 'Bank information',       anyOf: ['Bank Information'], requireVerified: true },
    ],
    High: [
      { name: 'Insurance (COI)',        anyOf: ['Insurance Certificate'], critical: true },
      { name: 'NDA',                    anyOf: ['NDA'], critical: true },
      { name: 'Contract / MSA',         anyOf: ['Contract'] },
      { name: 'Tax document (W-9/W-8)', anyOf: ['Tax Document'] },
      { name: 'Security attestation',   anyOf: ['SOC 2 Report','ISO Certificate','Security Certification'] },
      { name: 'Bank information',       anyOf: ['Bank Information'], requireVerified: true },
    ],
    Standard: [
      { name: 'NDA',                    anyOf: ['NDA'] },
      { name: 'Contract / MSA',         anyOf: ['Contract'] },
      { name: 'Tax document (W-9/W-8)', anyOf: ['Tax Document'] },
      { name: 'Bank information',       anyOf: ['Bank Information'], requireVerified: true },
    ],
  },
}}];

// Evaluate every active vendor against its tier requirements
const cfg = $('Set Tier Requirements').first().json;
const vendors = $('Fetch Vendors from Sheets').all().map(i => i.json)
  .filter(v => v.vendor_id && String(v.status || 'Active').toLowerCase() === 'active');
const docs = $('Fetch Documents from Sheets').all().map(i => i.json).filter(d => d.vendor_id);

const DAY = 86400000;
// all dates handled as UTC calendar days (local "today" of the n8n instance timezone)
const now = new Date();
const today = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
const iso = d => d ? d.toISOString().slice(0, 10) : '';
const parse = s => {
  if (!s) return null;
  const str = String(s).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return new Date(str + 'T00:00:00Z');
  const d = new Date(str);
  return isNaN(d) ? null : new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
};
const weekly = now.getDay() === cfg.weeklyReminderDay;
const RANK = { Valid: 3, Expiring: 2, 'No Expiry Date': 1, Expired: 0 };
const SEV = { Critical: 0, High: 1, Medium: 2 };
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

const out = [];
for (const v of vendors) {
  const tier = cfg.requirements[v.tier] ? v.tier : 'Standard';
  const reqs = cfg.requirements[tier];
  const vDocs = docs.filter(d => String(d.vendor_id) === String(v.vendor_id)).map(d => {
    let exp = parse(d.expiry_date);
    const issued = parse(d.issue_date);
    if (!exp && issued && cfg.defaultValidityDays[d.doc_type]) exp = new Date(issued.getTime() + cfg.defaultValidityDays[d.doc_type] * DAY);
    const days = exp ? Math.round((exp - today) / DAY) : null;
    let status = 'Valid';
    if (cfg.expiringTypes.includes(d.doc_type) && !exp) status = 'No Expiry Date';
    else if (days !== null && days < 0) status = 'Expired';
    else if (days !== null && days <= cfg.expiringSoonDays) status = 'Expiring';
    return { ...d, exp: iso(exp), days, status, isVerified: String(d.verified).toUpperCase() === 'TRUE' };
  });

  const issues = [];   // { severity, requirement, problem, vendorAction }
  const upcoming = [];
  let met = 0, remindToday = false;

  for (const req of reqs) {
    const best = vDocs.filter(d => req.anyOf.includes(d.doc_type))
      .sort((a, b) => (RANK[b.status] - RANK[a.status]) || ((b.days ?? 1e6) - (a.days ?? 1e6)))[0];
    const sev = req.critical ? 'Critical' : 'High';
    if (!best) { issues.push({ severity: sev, requirement: req.name, problem: 'Missing', vendorAction: true }); continue; }
    if (best.status === 'Expired') {
      issues.push({ severity: sev, requirement: req.name, problem: `Expired on ${best.exp} (${-best.days} days ago)`, vendorAction: true });
      continue;
    }
    if (req.requireVerified && !best.isVerified) {
      issues.push({ severity: 'Critical', requirement: req.name, problem: 'Not verified - do a call-back verification before releasing any payment', vendorAction: false });
      continue;
    }
    if (best.status === 'No Expiry Date') {
      issues.push({ severity: 'Medium', requirement: req.name, problem: 'Expiry date not recorded in register', vendorAction: false });
      met += 0.5; continue;
    }
    met += 1;
    if (best.status === 'Expiring') {
      issues.push({ severity: best.days <= 14 ? 'High' : 'Medium', requirement: req.name, problem: `Expires on ${best.exp} (in ${best.days} days)`, vendorAction: true });
      upcoming.push({ requirement: req.name, exp: best.exp, days: best.days });
      if (cfg.reminderDays.includes(best.days)) remindToday = true;
    }
  }

  issues.sort((a, b) => SEV[a.severity] - SEV[b.severity]);
  const score = Math.round((met / reqs.length) * 100);
  const critical = issues.filter(i => i.severity === 'Critical').length;
  const high = issues.filter(i => i.severity === 'High').length;
  const status = critical ? 'Non-Compliant' : (issues.length ? 'At Risk' : 'Compliant');
  const vendorItems = issues.filter(i => i.vendorAction);
  const hasMissingOrExpired = vendorItems.some(i => i.problem === 'Missing' || i.problem.startsWith('Expired'));
  const sendReminder = !!v.contact_email && vendorItems.length > 0 && (remindToday || (weekly && hasMissingOrExpired));

  const rows = vendorItems.map(i => `<tr><td style="padding:6px 10px;border:1px solid #ddd">${esc(i.requirement)}</td><td style="padding:6px 10px;border:1px solid #ddd">${esc(i.problem)}</td></tr>`).join('');
  const vendorEmailHtml = `<p>Hello ${esc(v.contact_name || v.vendor_name)},</p>
<p>As part of ${esc(cfg.companyName)}'s vendor compliance programme, we need the following documents from <b>${esc(v.vendor_name)}</b>:</p>
<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px"><tr style="background:#f3f4f6"><th style="padding:6px 10px;border:1px solid #ddd;text-align:left">Document</th><th style="padding:6px 10px;border:1px solid #ddd;text-align:left">Status</th></tr>${rows}</table>
<p>Please reply with the current documents (PDF) or send them to <a href="mailto:${cfg.complianceInbox}">${cfg.complianceInbox}</a>. Please do <b>not</b> email bank account details - our team will contact you to verify them by phone.</p>
<p>Thank you,<br>${esc(cfg.companyName)} Vendor Compliance</p>`;

  out.push({ json: {
    run_date: iso(today),
    vendor_id: v.vendor_id, vendor_name: v.vendor_name, tier,
    contact_name: v.contact_name || '', contact_email: v.contact_email || '', owner_email: v.owner_email || '',
    score, compliance_status: status, critical_count: critical, high_count: high,
    issues_text: issues.map(i => `[${i.severity}] ${i.requirement}: ${i.problem}`).join(' | '),
    issues, upcoming,
    send_vendor_reminder: sendReminder,
    vendor_email_subject: `Action required: compliance documents for ${v.vendor_name}`,
    vendor_email_html: vendorEmailHtml,
  }});
}
return out;

// Build the daily digest for the compliance owner + Slack summary
const cfg = $('Set Tier Requirements').first().json;
const r = $input.all().map(i => i.json);
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const count = s => r.filter(x => x.compliance_status === s).length;
const total = r.length;
const compliant = count('Compliant'), atRisk = count('At Risk'), nonCompliant = count('Non-Compliant');
const avg = total ? Math.round(r.reduce((a, x) => a + x.score, 0) / total) : 0;
const order = { 'Non-Compliant': 0, 'At Risk': 1, 'Compliant': 2 };
const tierOrder = { Critical: 0, High: 1, Standard: 2 };
const flagged = r.filter(x => x.compliance_status !== 'Compliant')
  .sort((a, b) => order[a.compliance_status] - order[b.compliance_status] || tierOrder[a.tier] - tierOrder[b.tier] || a.score - b.score);
const upcoming = r.flatMap(x => x.upcoming.map(u => ({ ...u, vendor: x.vendor_name, tier: x.tier }))).sort((a, b) => a.days - b.days);
const reminders = r.filter(x => x.send_vendor_reminder).length;
const color = s => s === 'Non-Compliant' ? '#b91c1c' : s === 'At Risk' ? '#b45309' : '#15803d';
const td = 'style="padding:6px 8px;border:1px solid #e5e7eb;vertical-align:top"';

const html = `<div style="font-family:Arial,sans-serif;font-size:13px;color:#111">
<h2 style="margin:0 0 4px">Vendor Compliance Digest - ${r[0]?.run_date || ''}</h2>
<p style="margin:0 0 12px">${total} active vendors · average score <b>${avg}%</b> · ${reminders} vendor reminder(s) sent${cfg.testMode ? ' (TEST MODE)' : ''}</p>
<table style="border-collapse:collapse;margin-bottom:16px"><tr>
<td ${td}><b style="color:#15803d">${compliant}</b> Compliant</td>
<td ${td}><b style="color:#b45309">${atRisk}</b> At Risk</td>
<td ${td}><b style="color:#b91c1c">${nonCompliant}</b> Non-Compliant</td></tr></table>
<h3>Vendors needing attention (${flagged.length})</h3>
${flagged.length ? `<table style="border-collapse:collapse"><tr style="background:#f3f4f6"><th ${td}>Vendor</th><th ${td}>Tier</th><th ${td}>Score</th><th ${td}>Status</th><th ${td}>Issues</th></tr>
${flagged.map(x => `<tr><td ${td}>${esc(x.vendor_name)}<br><span style="color:#6b7280">${esc(x.vendor_id)}</span></td><td ${td}>${x.tier}</td><td ${td}>${x.score}%</td><td ${td} ><b style="color:${color(x.compliance_status)}">${x.compliance_status}</b></td><td ${td}>${x.issues.map(i => `<b>${i.severity}</b> - ${esc(i.requirement)}: ${esc(i.problem)}`).join('<br>')}</td></tr>`).join('')}</table>` : '<p>None - all vendors compliant.</p>'}
<h3>Expiring in the next ${cfg.expiringSoonDays} days (${upcoming.length})</h3>
${upcoming.length ? `<table style="border-collapse:collapse"><tr style="background:#f3f4f6"><th ${td}>Vendor</th><th ${td}>Document</th><th ${td}>Expires</th><th ${td}>Days</th></tr>
${upcoming.map(u => `<tr><td ${td}>${esc(u.vendor)}</td><td ${td}>${esc(u.requirement)}</td><td ${td}>${u.exp}</td><td ${td}>${u.days}</td></tr>`).join('')}</table>` : '<p>Nothing expiring.</p>'}
</div>`;

const top = flagged.filter(x => x.compliance_status === 'Non-Compliant').slice(0, 10)
  .map(x => `• *${x.vendor_name}* (${x.tier}, ${x.score}%) - ${x.issues.filter(i => i.severity === 'Critical').map(i => `${i.requirement}: ${i.problem}`).join('; ')}`).join('\n');
const slack = `:shield: *Vendor Compliance - ${r[0]?.run_date || ''}*\n` +
  `${total} vendors | :white_check_mark: ${compliant} compliant | :warning: ${atRisk} at risk | :red_circle: ${nonCompliant} non-compliant | avg ${avg}%\n` +
  `${upcoming.length} document(s) expiring within ${cfg.expiringSoonDays} days | ${reminders} vendor reminder(s) sent` +
  (top ? `\n\n*Critical gaps:*\n${top}` : '');

return [{ json: { html, slack, subject: `Vendor Compliance: ${nonCompliant} non-compliant, ${atRisk} at risk (${r[0]?.run_date || ''})`, to: cfg.complianceOwnerEmail } }];
